#include "stdafx.h"#include "ServerThreadPipe.h"#include "EnumQueryTypes.h"#include "ExerciseState.h"#include "LogFile.h"#define READWRITE_CHUNKS#define MAX_CHUNK_SIZE		32768extern CExerciseState& GetExrcState();KServerThreadPipe::KServerThreadPipe( HANDLE hPipe ): m_hPipe(hPipe){}KServerThreadPipe::~KServerThreadPipe(){  FlushFileBuffers(m_hPipe);   DisconnectNamedPipe(m_hPipe);   CloseHandle(m_hPipe);}BOOL KServerThreadPipe::ReadData( PVOID lpBuffer, DWORD nNumberOfBytesToRead, LPDWORD lpNumberOfBytesRead ){	CLogFile::Log ("KServerThreadPipe::ReadData_0: nNumberOfBytesToRead %d", nNumberOfBytesToRead);#ifdef READWRITE_CHUNKS	BYTE *pPtr = (BYTE *)lpBuffer;	DWORD dwTotalRead = 0, dwCurSize = min (MAX_CHUNK_SIZE, nNumberOfBytesToRead);	while ( dwTotalRead < nNumberOfBytesToRead )	{		DWORD dwCurRead = 0;		BOOL bResult = ReadFile (m_hPipe, pPtr, dwCurSize, &dwCurRead, NULL);		if ( dwCurSize != dwCurRead )		{			DWORD dwError = GetLastError();			CLogFile::Log ("KServerThreadPipe::ReadData_FALSE_1: bResult %d, dwError %d, dwCurSize %d, dwCurRead %d", bResult, dwError, dwCurSize, dwCurRead);			return FALSE;		}		if ( !bResult )		{			DWORD dwError = ::GetLastError();			if ( dwError != ERROR_MORE_DATA )			{				CLogFile::Log ("KServerThreadPipe::ReadData_FALSE_2: dwError %d", dwError);				return FALSE;			}		}		if ( !bResult || (dwCurSize != dwCurRead) )		{			CLogFile::Log ("KServerThreadPipe::ReadData_FALSE_2: bResult %d, dwCurSize %d, dwCurRead %d", bResult, dwCurSize, dwCurRead);			return FALSE;		}		pPtr += dwCurSize;		dwTotalRead += dwCurRead;		DWORD dwReminder = (nNumberOfBytesToRead - dwTotalRead);		dwCurSize = min (MAX_CHUNK_SIZE, dwReminder);	}	*lpNumberOfBytesRead = dwTotalRead;	CLogFile::Log ("KServerThreadPipe::ReadData_1: dwTotalRead %d", dwTotalRead);	return TRUE;#else	BOOL fSuccess = ReadFile( m_hPipe, lpBuffer, nNumberOfBytesToRead, lpNumberOfBytesRead, NULL);	return fSuccess;#endif // READWRITE_CHUNKS}BOOL KServerThreadPipe::WriteData( LPCVOID lpBuffer, DWORD nNumberOfBytesToWrite, LPDWORD lpNumberOfBytesWritten ){#ifdef READWRITE_CHUNKS	CLogFile::Log ("KServerThreadPipe::WriteData_0: nNumberOfBytesToWrite %d", nNumberOfBytesToWrite);	BYTE *pPtr = (BYTE *)lpBuffer;	DWORD dwTotalWritten = 0, dwCurSize = min (MAX_CHUNK_SIZE, nNumberOfBytesToWrite);	while ( dwTotalWritten < nNumberOfBytesToWrite )	{		DWORD dwCurWritten = 0;		BOOL bResult = WriteFile (m_hPipe, pPtr, dwCurSize, &dwCurWritten, NULL);		if ( !bResult || (dwCurSize != dwCurWritten) )		{			DWORD dwError = GetLastError();			CLogFile::Log ("KServerThreadPipe::WriteData_FALSE_1: bResult %d, dwError %d, dwCurSize %d, dwCurWritten %d", bResult, dwError, dwCurSize, dwCurWritten);			return FALSE;		}		pPtr += dwCurSize;		dwTotalWritten += dwCurWritten;		DWORD dwReminder = (nNumberOfBytesToWrite - dwTotalWritten);		dwCurSize = min (MAX_CHUNK_SIZE, dwReminder);	}	*lpNumberOfBytesWritten = dwTotalWritten;	CLogFile::Log ("KServerThreadPipe::WriteData_1: dwTotalWritten %d", dwTotalWritten);	return TRUE;#else	BOOL fSuccess = WriteFile( m_hPipe, lpBuffer, nNumberOfBytesToWrite, lpNumberOfBytesWritten, NULL );	return fSuccess;#endif // READWRITE_CHUNKS}void KServerThreadPipe::GetAnswerToRequest(CMemBuffer& Reply){	DWORD qType = (*(QueryTypes*)m_pRequest) & (~id_MaskRsuNumber); //query type	CLogFile::Log ("KServerThreadPipe::GetAnswerToRequest: qType %d", qType);	if ( !m_bMainThread || (qType != qExrcState && qType != qRequestTip) )	{		KServerThreadBase::GetAnswerToRequest(Reply);		return;	}	CExerciseState& cExrcState = GetExrcState ();	size_t pos = sizeof(qType);	Reply.SeekToBegin ();	Reply.SetLength (0);	char *szUser;	GetFromReq (szUser, pos);	DWORD dwSize;	if ( qType == qExrcState )	{		DWORD dwState = cExrcState.GetUserState (szUser);		dwSize = sizeof(DWORD);		Reply.Write (&dwState, sizeof(DWORD));	}	else	{		CString cTipFile;		cExrcState.GetUserTip (szUser, cTipFile, TRUE);		dwSize = cTipFile.GetLength() + 1;		Reply.Write ((LPCTSTR)cTipFile, dwSize);	}}